@import url("https://fontsapi.zeoseven.com/256/main/result.css");
@font-face {
  font-family: "fugu";
  src: url("https://files.catbox.moe/qv2r9v.woff") format("woff"); /* 关键修改点 */
  font-display: swap;
  font-weight: normal;
  font-style: normal;
}
:root {
    --mainFontFamily: 'fugu';
    --black30a: #eceff98a;
    --black70a: rgb(213 221 240);
    --black50a: #ffffff;
    --grey30a: rgb(255 255 255 / 30%);
    --white50a: rgb(89 89 89 / 50%);
    --golden: rgb(135 153 202);
    --white30a: #545E7688;
}
body, input, textarea, select, code{
  font-family: "fugu", "Microsoft YaHei", sans-serif  !important;
}
/* 隐藏滑动条 */
*{
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE/Edge */
}

/* WebKit浏览器 (Chrome/Safari) */
*::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
/* 强制覆盖所有禁用元素的样式 */
[disabled], 
:disabled {
    /* 移除灰色滤镜和背景 */
    filter: none !important;
    background-color: transparent !important;
    background-image: none !important;

    /* 恢复文字颜色 */
    color: var(--text-normal) !important; /* 使用主题变量 */
    opacity: 1 !important;

    /* 修复边框 */
    border-color: var(--border-color-primary) !important;

    /* 修复图标颜色 */
    svg, img {
        opacity: 1 !important;
        filter: none !important;
    }
}

/* 针对特定禁用按钮的强化覆盖 */
button[disabled] {
    background: linear-gradient(to bottom, #f0f0f0, #e0e0e0) !important;
    color: #666 !important;
    border: 1px solid #d0d0d0 !important;
}

/* 修复输入框禁用状态 */
input[disabled], 
textarea[disabled] {
    background: #fff !important;
    -webkit-text-fill-color: #333 !important; /* 修复 Safari/Chrome 文字颜色 */
}

* {
    filter: none !important;
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-shadow: 0px 0px calc(var(--shadowWidth) * 1px) var(--SmartThemeShadowColor);
}

#chat {
    padding: 0px 15px;
    display: flex
;
    background-color: var(--SmartThemeChatTintColor);
    align-items: center !important;
}

/* 移动端适配 */
@media (max-width: 768px) {
    [data-is-user="true"] .mes-block,
    [data-is-user="false"] .mes-block {
        margin-left: 5% !important;
        margin-right: 5% !important;
        border-radius: 12px !important;
    }

