#chat .mes {
    display: flex;
    align-items: center;
    width: 98%;
    margin: 30px 0px 150px 0px !important;
    position: relative;
    flex-direction: column;
   padding: 0px !important;
}
#chat .mes::before {
    content: "";
    position: absolute;
    bottom: -60px;
    left: 0;
    right: 0;
    background: url(https://i.postimg.cc/KvL5nGh6/4.png) bottom center no-repeat;
    background-size: 100% auto;
    height: 200px;
    width: 100%;
    z-index: 0;
    font-family: "Huiwen-mincho";
}
.last_mes{
    margin-bottom: 25px !important;
}

#chat .mes .mesAvatarWrapper {
    width:100%;
    position: relative;
display: flex
;
    flex-direction: row;
    align-items: flex-end;
    aspect-ratio: 1634/2039;
    font-family: "Huiwen-mincho";
}


#chat .mes .mesAvatarWrapper::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    background: url(https://files.catbox.moe/jsuntd.png) top center no-repeat;
    background-size: 100% auto;
    height: 100%;
    z-index: -1;
    font-family: "Huiwen-mincho";
}

#chat .mes_block {
    position: relative; /* 创建定位上下文 */
    padding: 0px 15px; /* 移除原有padding */
    z-index: 1;
    min-height: 100px; /* 确保最小高度 */
    overflow: visible; /* 确保允许内容溢出 */
}

/* 顶部背景 - 使用伪元素 */
#chat .mes_block::before {
    content: "";
    position: absolute;
    top: -1px;
    left: 0;
    right: 0;
    height: 150px;
    background: url(https://i.postimg.cc/28gs28JZ/2.png) top center no-repeat;
    background-size: 100% auto;
    z-index: -1;
}

/* 中间背景 - 使用另一个伪元素 */
#chat .mes_block::after {
    content: "";
    position: absolute;
    top: 0px;
    bottom: -20px;
    left: 0;
    right: 0;
    background: url(https://i.postimg.cc/4N86gYZg/3.png) center repeat-y;
    z-index: -2;
}


.mes_text {
    padding-left: 8px;
    padding-top: 8px;
    padding-bottom: 8px;
    padding-right: 8px;
}

/*  楼层、计时器、token数 */
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    font-weight: normal;
    position: absolute;
}
/* 🌧️计时器位置，按顺序是下、左🌧️ */
.mes .mes_timer {
    bottom: 8px;
    left: 150px;
}
/* 🌧️楼层位置，按顺序是下、左🌧️ */
.mes .mesIDDisplay {
    bottom: 8px;
    left: 33px;
}
/* 🌧️token位置，按顺序是下、左🌧️ */
.mes .tokenCounterDisplay {
    bottom: 8px;
    left: 255px;
}


/* 用户最后一条消息 */
.last_mes .mesAvatarWrapper {
    padding: 0px;
}


/* 不知道叫什么总之搓了*/
.last_mes .flex-container {
    display: flex
;
    gap: 0px;
    flex-wrap: wrap;
}
.last_mes .alignItemsBaseline {
    align-items: baseline !important;
    display: flex
;
    flex-direction: column-reverse;
    padding-top: 0px;
    padding-left: 18px;
    font-family: "Huiwen-mincho";
}
mes .alignItemsBaseline .mes_ghost{
    padding-top: 0px;/* 隐藏楼层时的小幽灵标志的上面距离 */
}

#chat .mes .alignItemsBaseline {
    align-items: baseline !important;
    display: flex
;
    flex-direction: column-reverse;
    padding-top: 0px;
    padding-left: 5px;
    font-family: "Huiwen-mincho";
}
/* 🌧️名字位置，顺序上、左🌧️ */
#chat .mes .alignItemsBaseline .name_text {
    padding-top: 58px;
    padding-left: 5px;
}
/* 🌧️时间戳位置，顺序上、左🌧️ */
#chat .mes .alignItemsBaseline .timestamp {
    font-size: 0.8em;
    position: absolute;
    top: 23px;
    left: 30px;
}

/* 正则调整 */
.inline-drawer-content {
    padding-right: 30px;
}

/* 顶部 */
#top-bar {
    border-radius: 0px !important;
    box-shadow: none !important;
}

#top-settings-holder .drawer-toggle{
    padding: 0 !important; /* 移除内边距 */
    width: fit-content !important; /* 自适应图标宽度 */
}
#top-settings-holder .drawer-icon{
    padding: 4px; /* 图标周围保留4px点击区域 */
    font-size: 16px !important; /* 可选：缩小图标尺寸 */
}

#extensionTopBar {
    margin-top: 0px !important;
    border-radius: 0px !important;
    background-color: rgb(255 2255 255) !important;
}

/* 输入框 */
#send_form {
    height: auto !important;
    min-height: 45px !important;
    border-radius: 20px;
    width: -webkit-fill-available;
    border: 2px solid #6d779088 !important;
    margin: -2px 2px;
    flex-direction: row !important;
    justify-content: center !important;
    align-items: center;
    padding: 5px 10px;
}
/* 或精确控制伪元素（::before是图标本体） */
#leftSendForm ::before{
  font-size: 0.6em !important;
  width: 16px !important;
  height: 16px !important;
  padding-top: 6px;
}
/* 仅针对 rightSendForm 中【默认显示】的图标 */
#rightSendForm > .interactable:not([style*="display: none"]) .fa-solid,
#rightSendForm > .interactable[style*="display: flex"] .fa-solid {
    font-size: 0.6em !important;
    width: 16px !important;
    height: 16px !important;
    padding-bottom: 3px;
}
/* 特别处理发送按钮（飞机图标） */
#send_but.fa-solid {
  font-size: 0.6em !important; /* 单独调大 */
  padding-top: 6px;
}

/* 强制隐藏原本该隐藏的元素（安全锁） */
#mes_impersonate,
#mes_continue,
#stscript_stop:not(.active) { /* 非激活状态时隐藏 */
  display: none !important;
}
#quick-reply-rocket-button {
    font-size: 0.6em;
}
.fa-solid.fa-circle-stop {
    /* 隐藏Font Awesome的字体图标 */
    font-size: 0.6em !important;
}
/* 导入框 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, #sys-settings-button .drawer-content .inline-drawer-header, #ai-config-button .drawer-content .inline-drawer-header {
    border: 2px solid #d6ddf0b8 !important;
    position: relative;
    margin: 5px 0px;
    padding: 4px 10px !important;
    border-radius: 20px;
    background: #fff !important;
   box-shadow: 3px 3px 5px #d0d3db;
}
.userSettingsInnerExpandable, #sys-settings-button .drawer-content .inline-drawer-header, #ai-config-button .drawer-content .inline-drawer-header {
    background: #fff !important;
    padding: 6px 12px !important;
    border: 2px solid #d6ddf0b8 !important;
    border-radius: 20px;
   box-shadow: 3px 3px 5px #d0d3db;
}
select {
    background: linear-gradient(89deg, rgb(255 255 255) 10%, rgb(174 188 226 / 59%) 50%, rgb(255 255 255) 100%) !important;
    padding: 6px 8px !important;
    border-radius: 20px;
}
.fa-chevron-circle-up:before, .fa-circle-chevron-down:before,
.fa-chevron-circle-up:before, .fa-circle-chevron-up:before  {
    content: "\f145";
    color: #d6ddf0b8;
    font-size: calc(var(--mainFontSize) * 1.2);
}
/* 滑块 */
/* 清除所有浏览器默认外框 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 2px;
    border-radius: 0px;
    background-size: 70% 100%;
    background-repeat: no-repeat;
    box-shadow: none;
    cursor: ew-resize;
}
input[type="range"] {
    -webkit-appearance: none !important;
    border-radius: 0px !important;
    height: 2px !important;
    margin-bottom: 15px !important;
    background: #8799caaa !important;
    box-shadow: none !important;
}
input[type="number"] {
    background-color: rgb(234 238 247);
    border-radius: 20px;
}

input[disabled], textarea[disabled] {
    background:#8799ca !important;
    -webkit-text-fill-color: #333 !important;
}
/* 滑块按钮样式 */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  margin-top:5px;
  width:25px;
  height: 25px;
   border: none !important;
  background: url(https://i.postimg.cc/kG48rZQh/19-1.png) center/cover;
  cursor: pointer;
   background-size: contain;
   background-repeat: no-repeat;
}
/* 复选框 */
/* check框 */
input[type="checkbox"] {
    background: #fff;
    border: none;
    box-shadow: none;
  border-radius: 50%;
}
input[type="checkbox"]:checked {
    background: url(https://i.postimg.cc/ncHQyG9K/mhdsc888-38.png);
    width: 1.3em;
    height: 1.3em;
    background-size: contain;
    background-repeat: no-repeat;
    box-shadow: none;
    border: none !important;
    outline: none;
}
input[type="checkbox"]::before {
    box-shadow: none;
}
/* 正则 */
.regex-script-container {
    margin-right: 45px;
}
.regex-script-label {
    background: #a0aed533 !important;
    border-left: 1.5px solid #a0aed5b5 !important;
    border-radius: 20px !important;
    padding: 0px 10px 0px 10px !important;
}
.mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button,
.popup-controls .menu_button {
    background: #8799ca54 !important;
    margin-top: 50px;
}

#chat .mes.selected, .red_button, .redWarningBG {
    background-color: transparent !important;
}
.fav_on, .world_set, .toggleEnabled {
color: var(--golden) !important;
}
