.reasoning_edit_textarea, 
.edit_textarea {
    background-color: #ebeef7 !important;
}
.popup[open]::backdrop {
    background-color: #ffffff00 !important;
}
.world_entry {
    border: 2px solid #aebadc9e;
    margin: 20px 5px;
    padding: 5px;
    border-radius: 40px;
    box-shadow: 3px 3px 5px #d0d3db;
}
.tag {
    background-color: #dae1f2 !important;
    text-shadow: none !important;
}
/* 角色选择 */
.character_select.entity_block.flex-container.interactable.is_fav, #user_avatar_block .bogus_folder_select, #user_avatar_block .character_select, #user_avatar_block .avatar-container.selected {
border: 2px solid #d6ddf0b8 !important;
    position: relative;
    margin: 5px 0px;
    padding: 5px 10px !important;
    border-radius: 20px;
    background: #fff !important;
    box-shadow: 3px 3px 5px #d0d3db;
    width: 99%;
}
.character_select.is_fav .avatar {
    outline: none;
}
/* 预设 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls span {
    filter: none;
}
#completion_prompt_manager #completion_prompt_manager_list {
    background: #ffff;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background: transparent;
    box-shadow: none;
    border: none;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled::after{
    background: transparent !important;
}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    align-items: center;
    padding: 0.5em 1em;
    margin: 5px 0px;
    border: 2px solid rgb(212 219 239);
    position: relative;
    border-radius: 20px;
    background-color: #ffffff;
    box-shadow: 3px 3px 5px #d0d3db;
}
/* 思维链 */
.mes_reasoning_header {
    background: transparent;
    position: relative;
    margin: 0px 0px 0px 20px;
}
.mes_reasoning_header::after {
    background-image: url(https://i.postimg.cc/cJ9Bk5Lv/mhdsc888-82.png);
    content: "";
    position: absolute;
    width: 30px;
    height: 30px;
    background-size: contain;
    background-repeat: no-repeat;
    left: -15px;
    top: 3px;
    pointer-events: none;
    z-index: 10;
}
code {
    color: var(--SmartThemeBodyColor) !important;
    padding: 3px 10px;
    display: block;
    border-radius: 20px;
    background: #f0f2fa !important;
    outline: 1px dashed #8899ca;
    outline-offset: -3px;
    line-height: 18px;
}
